{
  "missionStatement": "Study the latest literature on room-temperature superconductors via online research and then update the repository's chemistry and physics proposals to reflect current understanding, including detailed mechanisms, synthesis routes, and characterization methods for at least three material families (hydrides, nickelates, cuprates).",
  "criteria": [
    {
      "description": "proposed_chemistry_physics.md contains a comprehensive proposal covering at least three distinct material families with detailed mechanisms, synthesis routes, and characterization methods, referencing recent literature.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "literature_review.md includes summaries and citations of at least 5 recent papers (2023-2025) on room-temperature superconductivity, with critical analysis of key findings.",
      "expectedFiles": ["literature_review.md"]
    },
    {
      "description": "theoretical_framework.md incorporates the latest theoretical models (BCS, Eliashberg, strong-coupling, dynamic Hubbard) and explains their applicability to the proposed material families.",
      "expectedFiles": ["theoretical_framework.md"]
    },
    {
      "description": "candidate_materials.md lists at least 10 candidate compounds with predicted Tc, synthesis pressure, stability criteria, and references to literature or DFT calculations.",
      "expectedFiles": ["candidate_materials.md"]
    },
    {
      "description": "synthesis_methods.md includes detailed protocols for high-pressure synthesis, doped hydride preparation, and thin-film growth, with safety and reproducibility notes.",
      "expectedFiles": ["synthesis_methods.md"]
    },
    {
      "description": "characterization_techniques.md describes modern methods such as ARPES, STM, muon spin rotation, and resistivity measurements, with expected signatures for each material family.",
      "expectedFiles": ["characterization_techniques.md"]
    },
    {
      "description": "discovery_strategy.md outlines a systematic workflow combining machine learning predictions, DFT screening, and high-throughput experimentation, with integration to the existing pipeline.",
      "expectedFiles": ["discovery_strategy.md"]
    },
    {
      "description": "experimental_feedback_loop.md describes an iterative design-build-test-learn cycle with automated data analysis and decision-making, referencing the pipeline and cloud lab integration.",
      "expectedFiles": ["experimental_feedback_loop.md"]
    },
    {
      "description": "dft_calculator.py is updated to support advanced functionals (SCAN, HSE06) and unit cell optimization for hydride structures, and includes a new test for a known superconductor (e.g., H3S).",
      "expectedFiles": ["dft_calculator.py", "tests/test_dft_calculator.py"]
    },
    {
      "description": "run_pipeline.py is updated to orchestrate the new workflow from literature screening through candidate generation to experimental protocol output, with command-line options for each stage.",
      "expectedFiles": ["run_pipeline.py"]
    },
    {
      "description": "A new file docs/online_research_summary.md is created summarizing the online research conducted, including key sources, URLs, and a synthesis of findings.",
      "expectedFiles": ["docs/online_research_summary.md"]
    },
    {
      "description": "A new file docs/novel_mechanism.md is created proposing a novel mechanism (e.g., exciton-mediated, plasmon-mediated, or interface-enhanced) for room-temperature superconductivity, with supporting arguments.",
      "expectedFiles": ["docs/novel_mechanism.md"]
    }
  ]
}

